def selectie_minim(L):
    n = len(L)
    for i in range(n):
        minim = i
        for j in range(i + 1, n):
            if L[j] < L[minim]:
                minim = j
        L[i], L[minim] = L[minim], L[i]
    return L

rez = selectie_minim([3, 1, 2])
print(rez)

